//! Mechanical emission of the IR in `ir.rs` to Steel.
//!
//! Bodies are built structurally as [`Sexp`]s and parsed exactly once per
//! top-level definition. Only primitive base-engine forms are emitted, that
//! is `if`, `begin`, `define`, `let` and `set!`. The VM runs
//! `Engine::new_base()`, which has no `cond` or `and` prelude.
//!
//! Emission contracts, shared with the node fns generated by `codegen`:
//!
//! - A node fn returns its single connected output raw. With more than one,
//!   it returns a `(list ...)` of its connected outputs in ascending index.
//! - A branching node fn returns `(list branch-ix value)`. The selected
//!   arm's active output count shapes `value`.
//! - A stateful node fn takes `state` as its trailing arg. A fn that may
//!   assign `state` returns `(list output state')`. One that only reads it
//!   returns its output alone. See [`StateUse`].
//!
//! The state of a level is a hashmap in the `graph-state` binding of its fn,
//! keyed by node id. A write puts the new value of one key into the map and
//! assigns the map back. See [`state_insert`].

use crate::{
    GRAPH_STATE,
    compile::{
        NodeConf, NodeConns,
        codegen::StateUse,
        ir::{Arg, Arm, Atom, Body, NodeCall, Step, Subject, Tail, Var},
        names::{STATE, join_name, node_fn_name, pair_name, var_name},
    },
    node,
};
use std::{collections::BTreeMap, fmt};
use steel::{parser::ast::ExprKind, steel_vm::engine::Engine};

/// The sentinel value marking a value that did not fire. See
/// [`Atom::Unfired`].
const UNFIRED: &str = "'%gantz-unfired";

/// A structurally built s-expression, displayed as Steel source.
#[derive(Clone, Debug)]
pub(crate) enum Sexp {
    /// An atom, printed verbatim.
    A(String),
    /// A parenthesised list.
    L(Vec<Sexp>),
}

/// Context fixed across one body's emission.
pub(crate) struct Cx<'a> {
    /// The path of the graph level being emitted, for node fn naming.
    pub path: &'a [node::Id],
    /// The state use of each stateful node fn variant of the level.
    pub state: &'a BTreeMap<NodeConf, StateUse>,
}

impl fmt::Display for Sexp {
    fn fmt(&self, f: &mut fmt::Formatter<'_>) -> fmt::Result {
        match self {
            Sexp::A(s) => write!(f, "{s}"),
            Sexp::L(items) => {
                write!(f, "(")?;
                for (i, item) in items.iter().enumerate() {
                    if i > 0 {
                        write!(f, " ")?;
                    }
                    write!(f, "{item}")?;
                }
                write!(f, ")")
            }
        }
    }
}

/// Shorthand for an atom.
pub(crate) fn a(s: impl Into<String>) -> Sexp {
    Sexp::A(s.into())
}

/// Shorthand for a list.
pub(crate) fn l(items: impl IntoIterator<Item = Sexp>) -> Sexp {
    Sexp::L(items.into_iter().collect())
}

/// The unit value `'()`.
pub(crate) fn unit() -> Sexp {
    a("'()")
}

fn atom_sexp(atom: &Atom) -> Sexp {
    match atom {
        Atom::Var(v) => a(var_name(v)),
        Atom::Unit => unit(),
        Atom::Unfired => a(UNFIRED),
    }
}

fn list_sexp(atoms: &[Atom]) -> Sexp {
    l(std::iter::once(a("list")).chain(atoms.iter().map(atom_sexp)))
}

/// The test that `atom` is the unfired sentinel.
fn unfired_test(atom: &Atom) -> Sexp {
    l([a("equal?"), atom_sexp(atom), a(UNFIRED)])
}

/// How a call passes one argument.
struct Input {
    /// `let` bindings to evaluate before the call, in order.
    lets: Vec<(String, Sexp)>,
    /// The value passed when the input is connected.
    value: Sexp,
    /// A test that is true when no source fired and the input is left
    /// unconnected. `None` when the input is always connected.
    unfired: Option<Sexp>,
}

/// How a call passes `arg` as input `ix`. An [`Arg::Maybe`] with several
/// sources collects the ones that fired into a list at runtime. Its value is
/// the only item of that list, or else the list.
fn input(ix: usize, arg: &Arg) -> Input {
    let fixed = |value| Input {
        lets: vec![],
        value,
        unfired: None,
    };
    let srcs = match arg {
        Arg::One(atom) => return fixed(atom_sexp(atom)),
        Arg::List(atoms) => return fixed(list_sexp(atoms)),
        Arg::Maybe(srcs) => srcs,
    };
    if let [(atom, true)] = srcs.as_slice() {
        return Input {
            lets: vec![],
            value: atom_sexp(atom),
            unfired: Some(unfired_test(atom)),
        };
    }
    let name = format!("%fired-{ix}");
    let fired = || a(name.clone());
    let mut lets = vec![(name.clone(), unit())];
    for (atom, maybe) in srcs.iter().rev() {
        let cons = l([a("cons"), atom_sexp(atom), fired()]);
        let next = if *maybe {
            l([a("if"), unfired_test(atom), fired(), cons])
        } else {
            cons
        };
        lets.push((name.clone(), next));
    }
    let only = l([a("null?"), l([a("cdr"), fired()])]);
    let value = l([a("if"), only, l([a("car"), fired()]), fired()]);
    let unfired = srcs
        .iter()
        .all(|&(_, maybe)| maybe)
        .then(|| l([a("null?"), fired()]));
    Input {
        lets,
        value,
        unfired,
    }
}

/// `body` within nested lets binding each of `lets` in order.
fn let_sexp(lets: Vec<(String, Sexp)>, body: Sexp) -> Sexp {
    lets.into_iter().rev().fold(body, |body, (name, value)| {
        l([a("let"), l([l([a(name), value])]), body])
    })
}

/// Bind `dst` from `value`. One var gets a plain define. Several vars get a
/// temporary bound to the `(list ...)` value, destructured by index.
///
/// `define-values` is not used. The base engine has no `values` to give it.
fn define_sexps(dst: &[Var], value: Sexp) -> Vec<Sexp> {
    match dst {
        [] => vec![value],
        [v] => vec![l([a("define"), a(var_name(v)), value])],
        _ => {
            let tmp = format!("%vals-{}", var_name(&dst[0]));
            let mut stmts = vec![l([a("define"), a(tmp.clone()), value])];
            for (k, v) in dst.iter().enumerate() {
                stmts.push(l([
                    a("define"),
                    a(var_name(v)),
                    l([a("list-ref"), a(tmp.clone()), a(k.to_string())]),
                ]));
            }
            stmts
        }
    }
}

/// The call expression for a node fn. A stateful call passes the state of
/// the node and writes back the state that the fn returns. With an
/// [`Arg::Maybe`], the expression tests which inputs got a source and calls
/// the variant that fits.
fn call_sexp(cx: &Cx, call: &NodeCall) -> Sexp {
    let inputs: Vec<Option<Input>> = call
        .args
        .iter()
        .enumerate()
        .map(|(ix, arg)| arg.as_ref().map(|arg| input(ix, arg)))
        .collect();
    let lets: Vec<(String, Sexp)> = inputs
        .iter()
        .flatten()
        .flat_map(|input| input.lets.iter().cloned())
        .collect();
    if !call.stateful {
        return let_sexp(lets, variant_sexp(cx, call, &inputs, vec![], None));
    }
    // A call of one variant that only reads the state takes it straight from
    // the map.
    let connected: Vec<bool> = inputs.iter().map(Option::is_some).collect();
    let one_variant = inputs.iter().flatten().all(|input| input.unfired.is_none());
    if one_variant && state_use(cx, call, &connected) == StateUse::Read {
        let state = state_ref(call.node);
        return let_sexp(lets, variant_sexp(cx, call, &inputs, vec![], Some(&state)));
    }
    let tree = variant_sexp(cx, call, &inputs, vec![], Some(&a(STATE)));
    let bind = l([a(STATE), state_ref(call.node)]);
    l([a("let"), l([bind]), let_sexp(lets, tree)])
}

/// The call of the node fn variant with the inputs that got a source. Each
/// input after the `connected` ones that may get none is tested in turn.
/// `state` is the expression of the state to pass, for a stateful call.
fn variant_sexp(
    cx: &Cx,
    call: &NodeCall,
    inputs: &[Option<Input>],
    connected: Vec<bool>,
    state: Option<&Sexp>,
) -> Sexp {
    let Some(input) = inputs.get(connected.len()) else {
        let mask = node::Conns::try_from_iter(connected.iter().copied())
            .expect("validated NodeCall arg count exceeds Conns::MAX");
        let node_path: Vec<node::Id> = cx.path.iter().copied().chain([call.node]).collect();
        let mut items = vec![a(node_fn_name(&node_path, &mask, &call.outputs))];
        let args = inputs.iter().zip(&connected).filter(|&(_, &c)| c);
        items.extend(args.filter_map(|(input, _)| input.as_ref().map(|i| i.value.clone())));
        let Some(state) = state else {
            return Sexp::L(items);
        };
        items.push(state.clone());
        return match state_use(cx, call, &connected) {
            StateUse::Read => Sexp::L(items),
            StateUse::Write => written_back(call.node, Sexp::L(items)),
        };
    };
    let with = |c: bool| {
        let mut connected = connected.clone();
        connected.push(c);
        variant_sexp(cx, call, inputs, connected, state)
    };
    match input {
        Some(Input {
            unfired: Some(test),
            ..
        }) => l([a("if"), test.clone(), with(false), with(true)]),
        Some(_) => with(true),
        None => with(false),
    }
}

/// How the node fn variant of `call` with the `connected` inputs uses its
/// state.
fn state_use(cx: &Cx, call: &NodeCall, connected: &[bool]) -> StateUse {
    let inputs = node::Conns::try_from_iter(connected.iter().copied())
        .expect("validated NodeCall arg count exceeds Conns::MAX");
    let conf = NodeConf {
        id: call.node,
        conns: NodeConns {
            inputs,
            outputs: call.outputs,
        },
    };
    // Every stateful variant that a body calls has a recorded use. Without
    // one there is no node fn either, and Steel rejects the call.
    cx.state.get(&conf).copied().unwrap_or(StateUse::Write)
}

/// Wrap the call of a node fn that returns `(list output state')`. Write the
/// returned state back and yield the output. `state` must be bound to the
/// state passed to the call.
fn written_back(node: node::Id, call_expr: Sexp) -> Sexp {
    let newstate = l([a("car"), l([a("cdr"), a("results")])]);
    l([
        a("let"),
        l([l([a("results"), call_expr])]),
        l([
            a("let"),
            l([l([a("newstate"), newstate])]),
            state_update(node, a(STATE), a("newstate")),
            l([a("car"), a("results")]),
        ]),
    ])
}

/// The state of `node` in the state map of the level.
pub(crate) fn state_ref(node: node::Id) -> Sexp {
    l([a("hash-ref"), a(GRAPH_STATE), a(format!("'{node}"))])
}

/// The statement that makes `new` the state of `node`, unless it is the
/// value `old` that the map has already. Both must be cheap to evaluate
/// twice, and neither may read the state map.
pub(crate) fn state_update(node: node::Id, old: Sexp, new: Sexp) -> Sexp {
    let same = l([a("eq?"), new.clone(), old]);
    l([a("if"), same, unit(), state_insert(node, new)])
}

/// The statement that inserts `value` as the state of `node`. `value` must
/// not read the state map.
///
/// The map moves out of `graph-state` for the insert. Steel inserts in place
/// only when nothing else refers to the map, and copies the map otherwise.
fn state_insert(node: node::Id, value: Sexp) -> Sexp {
    let taken = "%graph-state";
    let key = a(format!("'{node}"));
    let insert = l([a("hash-insert"), a(taken), key, value]);
    l([
        a("let"),
        l([l([a(taken), a(GRAPH_STATE)])]),
        l([a("set!"), a(GRAPH_STATE), a("#f")]),
        l([a("set!"), a(GRAPH_STATE), insert]),
    ])
}

/// The statements of a body. Its steps followed by exactly one tail
/// expression, which is the body's value.
pub(crate) fn body_sexps(cx: &Cx, body: &Body) -> Vec<Sexp> {
    let mut stmts = steps_sexps(cx, body);
    stmts.push(tail_sexp(&body.tail));
    stmts
}

/// The statements of the steps of a body, without its tail.
pub(crate) fn steps_sexps(cx: &Cx, body: &Body) -> Vec<Sexp> {
    let mut stmts = Vec::with_capacity(body.steps.len() + 1);
    for step in &body.steps {
        match step {
            Step::Node { dst, call } => {
                stmts.extend(define_sexps(dst, call_sexp(cx, call)));
            }
            Step::DelayRead { node } => {
                let var = Var::Output {
                    node: *node,
                    output: 0,
                };
                stmts.push(l([a("define"), a(var_name(&var)), state_ref(*node)]));
            }
            Step::DelayWrite { node, arg } => {
                let input = input(0, arg);
                let write = state_insert(*node, input.value);
                // An input with no source fired writes nothing.
                let stmt = match input.unfired {
                    Some(test) => l([a("if"), test, unit(), write]),
                    None => write,
                };
                stmts.push(let_sexp(input.lets, stmt));
            }
            Step::Join(join) => {
                let mut sig = vec![a(join_name(join.id))];
                sig.extend(join.params.iter().map(|p| a(var_name(p))));
                let mut items = vec![a("define"), Sexp::L(sig)];
                items.extend(body_sexps(cx, &join.body));
                stmts.push(Sexp::L(items));
            }
            Step::Branch { subject, dst, arms } => {
                let pair = match subject {
                    Subject::Call(call) => {
                        let pair = pair_name(call.node);
                        stmts.push(l([a("define"), a(pair.clone()), call_sexp(cx, call)]));
                        pair
                    }
                    // Bound by enclosing glue.
                    Subject::PreBound { node } => pair_name(*node),
                };
                stmts.extend(define_sexps(dst, dispatch_sexp(cx, &pair, arms)));
            }
        }
    }
    stmts
}

/// The dispatch expression over a branch's arms. Nested `if`s on the pair's
/// branch index. The last arm is the exhaustive fallthrough.
fn dispatch_sexp(cx: &Cx, pair: &str, arms: &[Arm]) -> Sexp {
    let ix_expr = || l([a("list-ref"), a(pair), a("0")]);
    let mut expr = unit();
    for (pos, arm) in arms.iter().enumerate().rev() {
        let arm_expr = arm_sexp(cx, pair, arm);
        if pos + 1 == arms.len() {
            expr = arm_expr;
        } else {
            let test = l([a("="), a(arm.ix.to_string()), ix_expr()]);
            expr = l([a("if"), test, arm_expr, expr]);
        }
    }
    expr
}

/// One arm's expression. Bind the arm's active outputs from the pair's value,
/// then the arm body. Wrapped in `(let () ...)` so the defines form a body.
fn arm_sexp(cx: &Cx, pair: &str, arm: &Arm) -> Sexp {
    let value = || l([a("list-ref"), a(pair), a("1")]);
    let binds = match arm.binds.as_slice() {
        [] => vec![],
        binds => define_sexps(binds, value()),
    };
    let body = body_sexps(cx, &arm.body);
    match (binds.is_empty(), arm.body.steps.is_empty()) {
        // No bindings or local steps. The tail expression alone suffices.
        (true, true) => body.into_iter().next().expect("body yields a tail expr"),
        _ => {
            let mut items = vec![a("let"), l([])];
            items.extend(binds);
            items.extend(body);
            Sexp::L(items)
        }
    }
}

/// The tail expression. The yielded values or a join tail-call.
fn tail_sexp(tail: &Tail) -> Sexp {
    match tail {
        Tail::Ret(atoms) => match atoms.as_slice() {
            [] => unit(),
            [atom] => atom_sexp(atom),
            atoms => l(std::iter::once(a("list")).chain(atoms.iter().map(atom_sexp))),
        },
        Tail::Jump { join, args } => {
            l(std::iter::once(a(join_name(*join))).chain(args.iter().map(atom_sexp)))
        }
    }
}

/// The result expression of a lowered level. The outlet values shaped by
/// activation pattern.
///
/// With fewer than two patterns the level never branches externally. The
/// result is then the outlet values directly. That is raw for one outlet, a
/// `(list ...)` for several, and `'()` for none. Otherwise the result is
/// `(list branch-ix value)`. The fired signature selects the pattern index.
/// It is the sum of `2^i` for each fired outlet, with conditional outlets
/// tested against the unfired sentinel. That pattern's active outlets shape
/// the value. This mirrors the `Node::branches` contract.
pub(crate) fn level_result_sexp(
    outlets: &[crate::compile::lower::OutletVal],
    patterns: &[node::Conns],
) -> Sexp {
    let atom = |o: &crate::compile::lower::OutletVal| match o.atom {
        Some(ref atom) => atom_sexp(atom),
        None => unit(),
    };
    let shaped = |active: Vec<&crate::compile::lower::OutletVal>| match active.as_slice() {
        [] => unit(),
        [o] => atom(o),
        os => l(std::iter::once(a("list")).chain(os.iter().map(|o| atom(o)))),
    };

    if patterns.len() < 2 {
        return shaped(outlets.iter().collect());
    }

    // The fired signature. Constant terms for unconditionally-fired outlets
    // and a sentinel test for conditional ones.
    let mut base: u128 = 0;
    let mut terms: Vec<Sexp> = Vec::new();
    for (i, o) in outlets.iter().enumerate() {
        match (o.atom, o.conditional) {
            (None, _) => {}
            (Some(_), false) => base += 1 << i,
            (Some(atom), true) => terms.push(l([
                a("if"),
                unfired_test(&atom),
                a("0"),
                a((1u128 << i).to_string()),
            ])),
        }
    }
    let sig_expr = match (base, terms.len()) {
        (b, 0) => a(b.to_string()),
        (0, 1) => terms.pop().unwrap(),
        (b, _) => {
            let mut items = vec![a("+"), a(b.to_string())];
            items.extend(terms);
            Sexp::L(items)
        }
    };

    // The unique signature of a pattern's active outlets.
    let signature = |conns: &node::Conns| -> u128 {
        (0..outlets.len())
            .filter(|&i| conns.get(i).unwrap_or(false))
            .map(|i| 1u128 << i)
            .sum()
    };
    let pattern_value = |conns: &node::Conns| -> Sexp {
        let active: Vec<&crate::compile::lower::OutletVal> = outlets
            .iter()
            .enumerate()
            .filter_map(|(i, o)| conns.get(i).unwrap_or(false).then_some(o))
            .collect();
        shaped(active)
    };

    // Nested `if` over patterns. The last is the exhaustive fallthrough.
    let last = patterns.len() - 1;
    let mut expr = l([
        a("list"),
        a(last.to_string()),
        pattern_value(&patterns[last]),
    ]);
    for k in (0..last).rev() {
        expr = l([
            a("if"),
            l([
                a("="),
                a("%gantz-sig"),
                a(signature(&patterns[k]).to_string()),
            ]),
            l([a("list"), a(k.to_string()), pattern_value(&patterns[k])]),
            expr,
        ]);
    }
    l([a("let"), l([l([a("%gantz-sig"), sig_expr])]), expr])
}

/// Assemble a top-level fn definition from glue statements.
///
/// A body that ends by returning the var its last statement defines calls
/// in tail position instead. A body that only calls a generated fn with the
/// params in order becomes an alias of that fn.
pub(crate) fn fn_def(name: &str, params: &[String], mut stmts: Vec<Sexp>) -> ExprKind {
    tail_call(&mut stmts);
    if let [Sexp::L(call)] = stmts.as_slice()
        && let Some(f) = eta_target(params, call)
    {
        return parse_one(&format!("(define {name} {f})"));
    }
    let mut sig = vec![a(name)];
    sig.extend(params.iter().map(|p| a(p.clone())));
    let mut items = vec![a("define"), Sexp::L(sig)];
    items.extend(stmts);
    parse_one(&Sexp::L(items).to_string())
}

/// Rewrite a trailing `(define x e) x` to `e`.
fn tail_call(stmts: &mut Vec<Sexp>) {
    let n = stmts.len();
    if n < 2 {
        return;
    }
    let (Sexp::L(def), Sexp::A(ret)) = (&stmts[n - 2], &stmts[n - 1]) else {
        return;
    };
    let [Sexp::A(kw), Sexp::A(var), _] = def.as_slice() else {
        return;
    };
    if kw != "define" || var != ret {
        return;
    }
    stmts.pop();
    let Some(Sexp::L(mut def)) = stmts.pop() else {
        unreachable!()
    };
    stmts.push(def.pop().expect("define has a value"));
}

/// The generated fn that the parsed `expr` applies to exactly `params`, in
/// order.
pub(crate) fn eta_target_expr(params: &[String], expr: &ExprKind) -> Option<String> {
    let ExprKind::List(list) = expr else {
        return None;
    };
    let call = list
        .args
        .iter()
        .map(|arg| arg.atom_identifier().map(|s| a(s.resolve())))
        .collect::<Option<Vec<_>>>()?;
    eta_target(params, &call).map(str::to_string)
}

/// The generated fn that `call` applies to exactly `params`, in order.
fn eta_target<'a>(params: &[String], call: &'a [Sexp]) -> Option<&'a str> {
    let (Sexp::A(f), args) = call.split_first()? else {
        return None;
    };
    let generated = f.starts_with("graph-fn-") || f.starts_with("node-fn-");
    let same = args.len() == params.len()
        && args
            .iter()
            .zip(params)
            .all(|(arg, p)| matches!(arg, Sexp::A(s) if s == p));
    (generated && same).then_some(f.as_str())
}

/// Parse one emitted top-level definition into the Steel AST.
pub(crate) fn parse_one(src: &str) -> ExprKind {
    Engine::emit_ast(src)
        .unwrap_or_else(|e| panic!("emitted Steel failed to parse: {e}\n{src}"))
        .into_iter()
        .next()
        .expect("emitted Steel parsed to no expression")
}

#[cfg(test)]
mod tests {
    use super::*;
    use crate::compile::ir::{self, Join};
    use steel::SteelVal;

    fn out(node: node::Id, output: usize) -> Var {
        Var::Output { node, output }
    }

    fn call(node: node::Id, args: Vec<Option<Arg>>, outputs: &str) -> NodeCall {
        NodeCall {
            node,
            args,
            outputs: outputs.parse().unwrap(),
            stateful: false,
        }
    }

    /// Emit `body` as a no-arg fn alongside the given node fn definitions,
    /// run it in a base VM, and return the result.
    fn run(node_fns: &[&str], body: &Body) -> SteelVal {
        ir::validate(body, 1, &[]).unwrap();
        let state = BTreeMap::new();
        let cx = Cx {
            path: &[],
            state: &state,
        };
        let mut src = node_fns.join(" ");
        // A test driver without state threading. Only the body statements.
        let mut items = vec![a("define"), l([a("test-fn")])];
        items.extend(body_sexps(&cx, body));
        src.push_str(&format!(" {}", Sexp::L(items)));
        let mut vm = Engine::new_base();
        vm.run(src).unwrap();
        vm.run("(test-fn)".to_string())
            .unwrap()
            .into_iter()
            .next()
            .unwrap()
    }

    /// A linear chain. A constant feeds a doubler, returning the result.
    #[test]
    fn linear_chain() {
        let body = Body {
            steps: vec![
                Step::Node {
                    dst: vec![out(0, 0)],
                    call: call(0, vec![], "1"),
                },
                Step::Node {
                    dst: vec![out(1, 0)],
                    call: call(1, vec![Some(Arg::One(Atom::Var(out(0, 0))))], "1"),
                },
            ],
            tail: Tail::Ret(vec![Atom::Var(out(1, 0))]),
        };
        let result = run(
            &[
                "(define (node-fn-0-o1) 21)",
                "(define (node-fn-1-i1-o1 input0) (* 2 input0))",
            ],
            &body,
        );
        assert_eq!(result, SteelVal::IntV(42));
    }

    /// A multi-output node destructures its outputs by index.
    #[test]
    fn multi_output_destructure() {
        let body = Body {
            steps: vec![
                Step::Node {
                    dst: vec![out(0, 0), out(0, 1)],
                    call: call(0, vec![], "11"),
                },
                Step::Node {
                    dst: vec![out(1, 0)],
                    call: call(
                        1,
                        vec![
                            Some(Arg::One(Atom::Var(out(0, 0)))),
                            Some(Arg::One(Atom::Var(out(0, 1)))),
                        ],
                        "1",
                    ),
                },
            ],
            tail: Tail::Ret(vec![Atom::Var(out(1, 0))]),
        };
        let result = run(
            &[
                "(define (node-fn-0-o11) (list 40 2))",
                "(define (node-fn-1-i11-o1 input0 input1) (+ input0 input1))",
            ],
            &body,
        );
        assert_eq!(result, SteelVal::IntV(42));
    }

    /// Multiple sources into one input pass as a `(list ...)` arg.
    #[test]
    fn list_arg() {
        let body = Body {
            steps: vec![
                Step::Node {
                    dst: vec![out(0, 0)],
                    call: call(0, vec![], "1"),
                },
                Step::Node {
                    dst: vec![out(1, 0)],
                    call: call(
                        1,
                        vec![Some(Arg::List(vec![
                            Atom::Var(out(0, 0)),
                            Atom::Var(out(0, 0)),
                        ]))],
                        "1",
                    ),
                },
            ],
            tail: Tail::Ret(vec![Atom::Var(out(1, 0))]),
        };
        let result = run(
            &[
                "(define (node-fn-0-o1) 21)",
                "(define (node-fn-1-i1-o1 input0) (+ (list-ref input0 0) (list-ref input0 1)))",
            ],
            &body,
        );
        assert_eq!(result, SteelVal::IntV(42));
    }

    /// A branch whose arms jump to a join. The join's param carries the
    /// arm-varying value and the branch exports the join's result.
    #[test]
    fn branch_join_export() {
        let param = Var::Input { node: 2, input: 0 };
        let export = out(2, 0);
        let arm = |ix: usize, output: usize| Arm {
            ix,
            binds: vec![out(1, output)],
            body: Body {
                steps: vec![],
                tail: Tail::Jump {
                    join: 2,
                    args: vec![Atom::Var(out(1, output))],
                },
            },
        };
        let body = Body {
            steps: vec![
                Step::Node {
                    dst: vec![out(0, 0)],
                    call: call(0, vec![], "1"),
                },
                Step::Join(Join {
                    id: 2,
                    params: vec![param],
                    rec: false,
                    body: Body {
                        steps: vec![Step::Node {
                            dst: vec![out(2, 0)],
                            call: call(2, vec![Some(Arg::One(Atom::Var(param)))], "1"),
                        }],
                        tail: Tail::Ret(vec![Atom::Var(out(2, 0))]),
                    },
                }),
                Step::Branch {
                    subject: Subject::Call(call(
                        1,
                        vec![Some(Arg::One(Atom::Var(out(0, 0))))],
                        "11",
                    )),
                    dst: vec![export],
                    arms: vec![arm(0, 0), arm(1, 1)],
                },
            ],
            tail: Tail::Ret(vec![Atom::Var(export)]),
        };
        let node_fns = [
            // Selects arm 1, yielding 20.
            "(define (node-fn-0-o1) 20)",
            // Arm 0 when input < 10, else arm 1. The value passes through.
            "(define (node-fn-1-i1-o11 input0)
               (if (< input0 10) (list 0 input0) (list 1 input0)))",
            "(define (node-fn-2-i1-o1 input0) (+ input0 1))",
        ];
        let result = run(&node_fns, &body);
        assert_eq!(result, SteelVal::IntV(21));
    }

    /// A rec join expresses a loop. Iterate until the count reaches zero.
    #[test]
    fn rec_join_loop() {
        let acc = Var::Input { node: 1, input: 0 };
        let n = Var::Input { node: 1, input: 1 };
        let body = Body {
            steps: vec![Step::Join(Join {
                id: 1,
                params: vec![acc, n],
                rec: true,
                body: Body {
                    steps: vec![Step::Branch {
                        subject: Subject::Call(call(
                            1,
                            vec![Some(Arg::One(Atom::Var(acc))), Some(Arg::One(Atom::Var(n)))],
                            "11",
                        )),
                        dst: vec![out(1, 0)],
                        arms: vec![
                            // Continue. Jump back with updated acc and n.
                            Arm {
                                ix: 0,
                                binds: vec![out(9, 0), out(9, 1)],
                                body: Body {
                                    steps: vec![],
                                    tail: Tail::Jump {
                                        join: 1,
                                        args: vec![Atom::Var(out(9, 0)), Atom::Var(out(9, 1))],
                                    },
                                },
                            },
                            // Exit. Yield the accumulator.
                            Arm {
                                ix: 1,
                                binds: vec![out(9, 0)],
                                body: Body {
                                    steps: vec![],
                                    tail: Tail::Ret(vec![Atom::Var(out(9, 0))]),
                                },
                            },
                        ],
                    }],
                    tail: Tail::Ret(vec![Atom::Var(out(1, 0))]),
                },
            })],
            tail: Tail::Jump {
                join: 1,
                args: vec![Atom::Unit, Atom::Unit],
            },
        };
        let node_fns = ["(define (node-fn-1-i11-o11 input0 input1)
            (let ((acc (if (number? input0) input0 0))
                  (n (if (number? input1) input1 100000)))
              (if (= n 0)
                  (list 1 acc)
                  (list 0 (list (+ acc 1) (- n 1))))))"];
        let result = run(&node_fns, &body);
        assert_eq!(result, SteelVal::IntV(100000));
    }
}
